import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';

import { LandingHeaderComponent } from './components/landing-header/landing-header.component';
import { LandingFooterComponent } from './components/landing-footer/landing-footer.component';
import { CompanyHeaderComponent } from './components/company-header/company-header.component';
import { CompanySidebarComponent } from './components/company-sidebar/company-sidebar.component';
import { CompanyShellComponent } from './components/company-shell/company-shell.component';
import { SeekerHeaderComponent } from './components/seeker-header/seeker-header.component';
import { SeekerSidebarComponent } from './components/seeker-sidebar/seeker-sidebar.component';
import { SeekerShellComponent } from './components/seeker-shell/seeker-shell.component';

@NgModule({
  declarations: [
    LandingHeaderComponent,
    LandingFooterComponent,
    CompanyHeaderComponent,
    CompanySidebarComponent,
    CompanyShellComponent,
    SeekerHeaderComponent,
    SeekerSidebarComponent,
    SeekerShellComponent
  ],
  imports: [
    CommonModule,
    RouterModule
  ],
  exports: [
    LandingHeaderComponent,
    LandingFooterComponent,
    CompanyHeaderComponent,
    CompanySidebarComponent,
    CompanyShellComponent,
    SeekerHeaderComponent,
    SeekerSidebarComponent,
    SeekerShellComponent
  ]
})
export class SharedModule { }
